import pypdf,glob,re,json,collections as C
pre={'MT':'NBBW','HT':'SZHT','LX':'YWLX','RF':'DGRF','MJ':'FSMJ','YD':'XMYD','QS':'NBQS','TY':'HZTY'}
out={}
for f in sorted(glob.glob('CI-PL_*.pdf')):
    t='\n'.join(p.extract_text() for p in pypdf.PdfReader(f).pages)
    out[f]=t
json.dump(out,open('$S/ci.json','w'))
tab=C.defaultdict(set)
for f,t in out.items():
    p=f.split('_')[1][:2]
    lines=t.split('\n')
    for i,l in enumerate(lines):
        m=re.match(r'^([A-Z]{2}-?\d{3,5}) (.*)',l)
        if m:
            hs=None
            for j in range(i+1,min(i+4,len(lines))):
                h=re.match(r'^(\d{4}\.\d{2}\.\d{4})',lines[j])
                if h: hs=h.group(1);break
            tab[(pre.get(p,p),m.group(1))].add((m.group(2),hs))
for k,v in sorted(tab.items()): print(k,v)
print(len(tab))
E

