na=[v for v in by3.values() if len(v)>1]
print('name+addr groups',len(na),C.Counter(len(v) for v in na))
# same name different mailboxes
for g in mb[:8]: print([ (i,cu[i]['raw'],cu[i]['nm'],oc[i]) for i in g])
print('---na')
for g in na[:8]: print([ (i,cu[i]['raw'],cu[i]['nm'],oc[i]) for i in g])
