print('cust w >1 raw email',sum(1 for c in cu.values() if len(c['raw'])>1))
json.dump({i:{'raw':sorted(c['raw']),'em':sorted(c['em']),'na':sorted(c['na']),'nm':c['nm']} for i,c in cu.items()},open('$S/cust.json','w'))
E

