S=/private/tmp/claude-501/-private-var-folders-qj-j67my3-j6bzb4y5t82bvmkfh0000gn-T-m5-t-ht3vspo0-catalogue-work/3bb3823c-b76d-46d3-ac13-b7234c350b67/scratchpad; python3 - <<E
import json,collections as C
cu=json.load(open('$S/cust.json'))
orders=[json.loads(l) for l in open('shopify/orders.jsonl')]
first={}
for o in orders:
    if '__parentId' in o: continue
    i=o['customer']['id'].split('/')[-1]
    first[i]=min(first.get(i,'9'),o['createdAt'])
by=C.defaultdict(set); by3=C.defaultdict(set)
for i,c in cu.items():
    for e in c['em']: by[e].add(i)
    for t in c['na']:
        if t[0] and t[1]!='|': by3[tuple(t)].add(i)
pairsA=set();pairsB=set()
def pr(g,S):
    g=sorted(g,key=lambda i:(first[i],i))
    for x in g[1:]: S.add((x,g[0]))
for g in by.values():
    if len(g)>1: pr(g,pairsA)
for g in by3.values():
    if len(g)>1: pr(g,pairsB)
print(len(pairsA),len(pairsB),len(pairsA&pairsB),len(pairsB-pairsA))
# name consistency in A
bad=[(a,b) for a,b in pairsA if [x.lower() for x in cu[a]['nm']]!=[x.lower() for x in cu[b]['nm']]]
print('A name mismatch',len(bad),bad[:5])
# B pairs whose mailbox local parts differ -- show sample
import random
random.seed(1)
Bo=sorted(pairsB-pairsA)
for a,b in random.sample(Bo,10): print(cu[a]['raw'],cu[a]['nm'],cu[a]['na'],'||',cu[b]['raw'],cu[b]['nm'],cu[b]['na'])
# a newer pointing to a survivor that itself is newer pointer? union all
par={}
for a,b in pairsA|pairsB:
    if a in par and par[a]!=b: print('conflict',a,par[a],b)
    par[a]=b
inc=C.Counter(par.values()); print('max incoming',inc.most_common(3), 'chain', sum(1 for b in par.values() if b in par))
json.dump({'A':sorted(pairsA),'B':sorted(pairsB-pairsA)},open('$S/pairs.json','w'))
E

