    assert len(code)<=1
    if code: f.append({'e':['supplier/code',code[0]],'a':'quickbooks/vendor','v':v['Vendor']}); seen.add(code[0])
    else: f.append({'e':['quickbooks/vendor',v['Vendor']],'a':'quickbooks/vendor','v':v['Vendor']}); print('no supplier:',v['Vendor'])
